json_ld:
["
	{
	          "@context" : "http://schema.org",
	          "@type" : "Organization",
	          "name" : "Tablet Hotels",
			  "description" : "Tablet is everything you need for unforgettable travel experiences: the best hotels curated for you with verified reviews, the lowest rates guaranteed & awesome customer service.",
			"image" :  "https://www.tablethotels.com/media/ecs/global/facebook-share-base.jpg",
	          "legalName": "Tablet LLC",
	          "url" : "https://www.tablethotels.com",
	          "sameAs" : [ "https://www.facebook.com/tablethotels",
	            "https://instagram.com/tablethotels/",
	            "http://pinterest.com/tablethotels",
	            "https://twitter.com/tablethotels"
		],
	          "contactPoint" : [{
	            "@type" : "ContactPoint",
	            "telephone" : "+1-646-880-3634",
	            "contactType" : "customer service"
	          }]
	        }
	", "
	{
	  "@context": "http://schema.org",
	  "@type": "WebSite",
	  "url": "https://www.tablethotels.com",
	  "name" : "Tablet Hotels",
	  "potentialAction": {
	    "@type": "SearchAction",
	    "target": "https://www.tablethotels.com/search/?query={search_term_string}",
	    "query-input": "required name=search_term_string"
	  }
	}
	", "
			{
				"@context": "https://schema.org",
				"@type": "FAQPage",
				"mainEntity": [{
					"@type": "Question",
					"name": "What is Tablet Hotels?",
					"acceptedAnswer": {
					"@type": "Answer",
					"text": "Tablet is your source for discovering the world's most interesting boutique & luxury hotels — places where you'll find a memorable experience, not just a room for the night. Part of the MICHELIN Guide since 2018, our hand-picked selection has hotels to meet every taste and budget, and we make booking them a joy. If you care where you stay, you've come to the right place."
					}
				}, {
					"@type": "Question",
					"name": "Do I need to be a member to use Tablet?",
					"acceptedAnswer": {
					"@type": "Answer",
					"text": "No, anyone can book on Tablet. But if you <a href='https://www.tablethotels.com/user'>create a Tablet account</a> before you book, you'll gain access to our private Insider Sale discounts. Or, <a href='https://www.tablethotels.com/en/tablet-plus'>sign up for a free trial</a> of Tablet Plus and you'll receive VIP perks and privileges at hundreds of participating hotels."
					}
				},
				{
					"@type": "Question",
					"name": "What is Tablet Plus?",
					"acceptedAnswer": {
					"@type": "Answer",
					"text": "For just $99 per year, Tablet Plus members receive VIP treatment at hundreds of participating Plus hotels, with perks like room upgrades, free breakfast, late check-out, airport transfers, spa credit, and more. Tablet Plus members also receive access to exclusive member-only deals at the world's finest hotels. <a href='https://www.tablethotels.com/en/tablet-plus'>Sign up for a free 30-day trial</a>."
					}
				},
				{
					"@type": "Question",
					"name": "Does Tablet offer discounts?",
					"acceptedAnswer": {
					"@type": "Answer",
					"text": "Every day you'll find a range of hotel deals all throughout Tablet:<br><b>Tablet Sale</b>: Deep discounts at the world's coolest hotels. Available daily to anyone using Tablet. No account needed.<br><b>Insider Sale</b>: Private hotel discounts available only to Tablet account holders. Don't get left out in the cold. <a href='https://www.tablethotels.com/user'>Get an account</a> and get lower prices.<br><b>Plus Member Sale</b>: VIP hotel discounts available only to Tablet Plus members. <a href='https://www.tablethotels.com/en/tablet-plus'>Start your free trial</a> to unlock these and other Tablet Plus perks.<br><b>Mobile Only Sale</b>: Be rewarded for being a traveler. Get a discount on your next trip, even during your current one.<br><b>Lucky Room</b>: You won't know your room until check-in, but you will know you scored an extra-low price."
					}
				},
				{
					"@type": "Question",
					"name": "Why should I book with you instead of Expedia or a traditional travel agent?",
					"acceptedAnswer": {
					"@type": "Answer",
					"text": "That's our favorite question. Here's why:<br><b>Curation</b>: For 20+ years we've scoured the earth to find the most interesting and extraordinary hotels — places where you'll get a memorable experience, not just a room for the night. Part of the MICHELIN Guide, our hand-picked selection is proven and dependable, with unique hotels to meet every taste and budget.<br><b>Rates</b>: We have the best rates online and discounts at hotels that *never* go on sale. Our team can help you locate deals and special offers and answer any questions about rate policies. And if you happen to find a lower rate elsewhere we'll match it and give you 6 months of Tablet Plus, absolutely free.<br><b>Service</b>: Our Travel Specialists are the best in the industry. We're a well-traveled team with years of experience recommending destinations and hotels, arranging special requests, modifying reservations, dealing with hiccups or last-minute emergencies, and making sure your trip goes as smoothly as possible.<br><b>Tablet Plus</b>: For just $99 per year, Tablet Plus members receive VIP treatment at hundreds of participating Plus hotels, with perks like room upgrades, free breakfast, late check-out, airport transfers, spa credit, and more.<br><b>Style and Substance</b>: The Tablet staff is diverse, dedicated, and well-dressed, and our website and <a href='https://geo.itunes.apple.com/us/app/tablet-hotels/id1105936328?mt=8'>iOS App</a> are a joy to use. Unlike our competitors, we focus only on hotels — not hotels, cars, planes, and cruise ships. From inspiration to confirmation, our passion for hotels and hospitality is clear."
					}
				},
				{
					"@type": "Question",
					"name": "Are hotels featured on Tablet expensive?",
					"acceptedAnswer": {
					"@type": "Answer",
					"text": "Our selection features thousands of boutique & luxury hotels in over 100 countries, and covers a wide range of price options — from budget boutique hotels that are low on price and long on personality, to spectacular luxury lodgings that must be seen to be believed. The only common denominator is that each hotel, rega"]

